mapper.select:
SELECT mr.*, u.real_name AS patient_name, u.phone AS patient_phone, a.appointment_date, a.time_slot FROM medical_record mr LEFT JOIN appointment a ON mr.appointment_id = a.id LEFT JOIN user u ON mr.patient_id = u.id WHERE mr.doctor_id = #{doctorId}
AND mr.visit_time >= #{startDate}
AND mr.visit_time <= #{endDate}
ORDER BY mr.visit_time DESC
